   for j in [4,5,7]: print(ps[j])
  else: print(y['proposed_xml'])
print('\\nValidation : 24 objets uniques ; identifiants exacts ; nombres, renvois numériques et structures de tableaux conservés ; balises conformes ; aucun texte réservé ou différé.')
